INSERT INTO Move (m_i_name, m_name, m_category, m_power, m_accuracy, m_range, m_description) VALUES ('MUDDYWATER','Muddy Water','Special', 90, 85,'AllNearFoes','The user attacks by shooting muddy water at the opposing team. It may also lower the target''s accuracy.');
INSERT INTO Move (m_i_name, m_name, m_category, m_power, m_accuracy, m_range, m_description) VALUES ('SPARKLINGARIA','Sparkling Aria','Special', 90, 100,'AllNearOthers','The user bursts into song, emitting many bubbles. Any burnt Pokemon will be healed by these bubbles.');
INSERT INTO Move (m_i_name, m_name, m_category, m_power, m_accuracy, m_range, m_description) VALUES ('SURF','Surf','Special', 90, 100,'AllNearOthers','It swamps the area around the user with a giant wave. It can also be used for crossing water.');
INSERT INTO Move (m_i_name, m_name, m_category, m_power, m_accuracy, m_range, m_description) VALUES ('FISHIOUSREND','Fishious Rend','Physical', 85, 100,'NearOther','The user rends the target with its hard gills. Power doubles if the user moves first.');
