INSERT INTO Move (m_i_name, m_name, m_category, m_power, m_accuracy, m_range, m_description) VALUES ('DIVE','Dive','Physical', 80, 100,'NearOther','Diving on the first turn, the user rises and hits on the next turn. It can be used to dive in the ocean.');
