INSERT INTO Move (m_i_name, m_name, m_category, m_power, m_accuracy, m_range, m_description) VALUES ('WATERFALL','Waterfall','Physical', 80, 100,'NearOther','The user charges at the target and may make it flinch. It can also be used to climb a waterfall.');
INSERT INTO Move (m_i_name, m_name, m_category, m_power, m_accuracy, m_range, m_description) VALUES ('RAZORSHELL','Razor Shell','Physical', 75, 95,'NearOther','The user cuts the foe with sharp shells. It may also lower the target''s Defense stat.');
INSERT INTO Move (m_i_name, m_name, m_category, m_power, m_accuracy, m_range, m_description) VALUES ('BRINE','Brine','Special', 65, 100,'NearOther','If the target''s HP is down to about half, this attack will hit with double the power.');
INSERT INTO Move (m_i_name, m_name, m_category, m_power, m_accuracy, m_range, m_description) VALUES ('BUBBLEBEAM','Bubble Beam','Special', 65, 100,'NearOther','A spray of bubbles is forcefully ejected at the target. It may also lower its Speed stat.');
INSERT INTO Move (m_i_name, m_name, m_category, m_power, m_accuracy, m_range, m_description) VALUES ('OCTAZOOKA','Octazooka','Special', 65, 85,'NearOther','The user attacks by spraying ink in the foe''s face or eyes. It may also lower the target''s accuracy.');
INSERT INTO Move (m_i_name, m_name, m_category, m_power, m_accuracy, m_range, m_description) VALUES ('FLIPTURN','Flip Turn','Physical', 60, 100,'NearOther','After making its attack, the user rushes back to switch places with a party Pokemon in waiting.');
INSERT INTO Move (m_i_name, m_name, m_category, m_power, m_accuracy, m_range, m_description) VALUES ('WATERPULSE','Water Pulse','Special', 60, 100,'Other','The user attacks the target with a pulsing blast of water. It may also confuse the target.');
INSERT INTO Move (m_i_name, m_name, m_category, m_power, m_accuracy, m_range, m_description) VALUES ('AQUAJET','Aqua Jet','Physical', 40, 100,'NearOther','The user lunges at the target at a speed that makes it almost invisible. It is sure to strike first.');
INSERT INTO Move (m_i_name, m_name, m_category, m_power, m_accuracy, m_range, m_description) VALUES ('BUBBLE','Bubble','Special', 40, 100,'AllNearFoes','A spray of countless bubbles is jetted at the opposing team. It may also lower the targets'' Speed stats.');
INSERT INTO Move (m_i_name, m_name, m_category, m_power, m_accuracy, m_range, m_description) VALUES ('WATERGUN','Water Gun','Special', 40, 100,'NearOther','The target is blasted with a forceful shot of water.');
INSERT INTO Move (m_i_name, m_name, m_category, m_power, m_accuracy, m_range, m_description) VALUES ('CLAMP','Clamp','Physical', 35, 85,'NearOther','The target is clamped and squeezed by the user''s very thick and sturdy shell for four to five turns.');
INSERT INTO Move (m_i_name, m_name, m_category, m_power, m_accuracy, m_range, m_description) VALUES ('WHIRLPOOL','Whirlpool','Special', 35, 85,'NearOther','Traps foes in a violent swirling whirlpool for four to five turns.');
INSERT INTO Move (m_i_name, m_name, m_category, m_power, m_accuracy, m_range, m_description) VALUES ('SURGINGSTRIKES','Surging Strikes','Physical', 25, 100,'NearOther','Hits three times in a row with mastery of the Water style. This attack always deals critical hits.');
INSERT INTO Move (m_i_name, m_name, m_category, m_power, m_accuracy, m_range, m_description) VALUES ('WATERSHURIKEN','Water Shuriken','Special', 15, 100,'NearOther','The user hits the target with throwing stars 2-5 times in a row. This move always goes first.');
INSERT INTO Move (m_i_name, m_name, m_category, m_power, m_accuracy, m_range, m_description) VALUES ('AQUARING','Aqua Ring','Status', null, 0,'User','The user envelops itself in a veil made of water. It regains some HP on every turn.');
INSERT INTO Move (m_i_name, m_name, m_category, m_power, m_accuracy, m_range, m_description) VALUES ('LIFEDEW','Life Dew','Status', null, 0,'UserAndAllies','The user scatters mysterious water around and restores the HP of itself and its allies.');
INSERT INTO Move (m_i_name, m_name, m_category, m_power, m_accuracy, m_range, m_description) VALUES ('RAINDANCE','Rain Dance','Status', null, 0,'BothSides','The user summons a heavy rain that falls for five turns, powering up Water-type moves.');
INSERT INTO Move (m_i_name, m_name, m_category, m_power, m_accuracy, m_range, m_description) VALUES ('SOAK','Soak','Status', null, 100,'NearOther','The user shoots a torrent of water at the target and changes the target''s type to Water.');
INSERT INTO Move (m_i_name, m_name, m_category, m_power, m_accuracy, m_range, m_description) VALUES ('WATERSPORT','Water Sport','Status', null, 0,'BothSides','The user soaks itself with water. The move weakens Fire-type moves while the user is in the battle.');
INSERT INTO Move (m_i_name, m_name, m_category, m_power, m_accuracy, m_range, m_description) VALUES ('WITHDRAW','Withdraw','Status', null, 0,'User','The user withdraws its body into its hard shell, raising its Defense stat.');
